-- Schema for the site content platform. See docs/implementation/contract.md.
-- IDs are UUIDv7 generated by the service, so no database extension is needed.

CREATE TABLE users (
    id uuid PRIMARY KEY,
    -- Null until the person first signs in with Keycloak.
    keycloak_sub text UNIQUE,
    andrew_id text NOT NULL UNIQUE CHECK (andrew_id ~ '^[a-z0-9][a-z0-9._-]{0,63}$'),
    name text NOT NULL DEFAULT '',
    email text,
    created_at timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz
);

CREATE TABLE committees (
    slug text PRIMARY KEY CHECK (
        slug IN ('events', 'outreach', 'tech', 'labrador', 'design', 'finance', 'foundry')
    ),
    name text NOT NULL,
    sort_order integer NOT NULL,
    color text NOT NULL,
    tint text NOT NULL
);

CREATE TABLE role_assignments (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role text NOT NULL CHECK (role IN ('admin', 'director', 'lead')),
    committee text REFERENCES committees (slug),
    can_post_ticker boolean NOT NULL DEFAULT true,
    appointed_by uuid REFERENCES users (id) ON DELETE SET NULL,
    source text NOT NULL CHECK (source IN ('keycloak_group', 'governance', 'portal')),
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK ((role = 'admin') = (committee IS NULL))
);

CREATE UNIQUE INDEX role_assignments_unique
    ON role_assignments (user_id, role, coalesce(committee, ''));
CREATE INDEX role_assignments_committee ON role_assignments (committee);

CREATE TABLE sessions (
    id uuid PRIMARY KEY,
    -- SHA-256 of the random cookie token. The token itself is never stored.
    token_hash bytea NOT NULL UNIQUE,
    user_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    csrf_token text NOT NULL,
    auth_mode text NOT NULL CHECK (auth_mode IN ('oidc', 'dev')),
    created_at timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL
);

CREATE INDEX sessions_user ON sessions (user_id);
CREATE INDEX sessions_expires ON sessions (expires_at);

-- One row per sign-in started, consumed by the callback. Short lived.
CREATE TABLE auth_attempts (
    csrf text PRIMARY KEY,
    pkce_verifier text NOT NULL,
    nonce text NOT NULL,
    return_to text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE media (
    id uuid PRIMARY KEY,
    content_type text NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png')),
    width integer NOT NULL CHECK (width > 0),
    height integer NOT NULL CHECK (height > 0),
    -- Widths that were generated, ascending, for example {480,960,1920}.
    variants integer[] NOT NULL,
    bytes bigint NOT NULL,
    storage text NOT NULL CHECK (storage IN ('s3', 'database')),
    uploaded_by uuid REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

-- Used only when no S3 bucket is configured.
CREATE TABLE media_blobs (
    media_id uuid NOT NULL REFERENCES media (id) ON DELETE CASCADE,
    width integer NOT NULL,
    data bytea NOT NULL,
    PRIMARY KEY (media_id, width)
);

CREATE TABLE committee_pages (
    committee text PRIMARY KEY REFERENCES committees (slug),
    -- CommitteePageDoc: { blocks: Block[], settings: CommitteeSettings }
    draft jsonb NOT NULL,
    published jsonb,
    draft_version integer NOT NULL DEFAULT 1,
    draft_updated_at timestamptz NOT NULL DEFAULT now(),
    draft_updated_by uuid REFERENCES users (id) ON DELETE SET NULL,
    published_at timestamptz,
    published_by uuid REFERENCES users (id) ON DELETE SET NULL,
    lock_user_id uuid REFERENCES users (id) ON DELETE SET NULL,
    lock_heartbeat_at timestamptz
);

CREATE TABLE projects (
    id uuid PRIMARY KEY,
    slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    -- Owner, used for permissions. Mirrors draft->>'committee'.
    committee text NOT NULL REFERENCES committees (slug),
    state text NOT NULL CHECK (state IN ('draft', 'published', 'archived')),
    -- ProjectDoc
    draft jsonb NOT NULL,
    published jsonb,
    featured boolean NOT NULL DEFAULT false,
    created_by uuid REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid REFERENCES users (id) ON DELETE SET NULL,
    published_at timestamptz,
    published_by uuid REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX projects_committee ON projects (committee);

-- Old slugs keep working after a rename.
CREATE TABLE project_slug_redirects (
    old_slug text PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE
);

-- Leads who may edit a project.
CREATE TABLE project_editors (
    project_id uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    added_by uuid REFERENCES users (id) ON DELETE SET NULL,
    added_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (project_id, user_id)
);

CREATE TABLE announcements (
    id uuid PRIMARY KEY,
    kind text NOT NULL CHECK (kind IN ('event', 'project_update', 'milestone', 'club_news')),
    -- A committee slug, or 'club' for ScottyLabs-wide news.
    committee text NOT NULL CHECK (
        committee IN ('club', 'events', 'outreach', 'tech', 'labrador', 'design', 'finance', 'foundry')
    ),
    message text NOT NULL CHECK (char_length(message) BETWEEN 1 AND 90),
    link_url text,
    -- pending_approval, live, sent_back or ended. "Expired" is derived from
    -- expires_at and is never stored.
    state text NOT NULL CHECK (state IN ('pending_approval', 'live', 'sent_back', 'ended')),
    starts_at timestamptz,
    expires_at timestamptz NOT NULL,
    ended_at timestamptz,
    position integer NOT NULL DEFAULT 0,
    created_by uuid REFERENCES users (id) ON DELETE SET NULL,
    approved_by uuid REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX announcements_live ON announcements (state, expires_at);

CREATE TABLE approvals (
    id uuid PRIMARY KEY,
    subject_type text NOT NULL CHECK (subject_type IN ('announcement', 'project')),
    subject_id uuid NOT NULL,
    committee text NOT NULL,
    submitted_by uuid REFERENCES users (id) ON DELETE SET NULL,
    -- What was submitted, so the approver sees exactly that.
    snapshot jsonb NOT NULL,
    status text NOT NULL CHECK (status IN ('waiting', 'approved', 'sent_back', 'withdrawn')),
    note text,
    decided_by uuid REFERENCES users (id) ON DELETE SET NULL,
    decided_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX approvals_status ON approvals (status, committee);
CREATE UNIQUE INDEX approvals_one_waiting
    ON approvals (subject_type, subject_id) WHERE status = 'waiting';

CREATE TABLE audit_log (
    id uuid PRIMARY KEY,
    actor_id uuid REFERENCES users (id) ON DELETE SET NULL,
    action text NOT NULL,
    subject_type text NOT NULL,
    subject_id text,
    committee text,
    summary text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX audit_log_created ON audit_log (created_at DESC);
CREATE INDEX audit_log_committee ON audit_log (committee, created_at DESC);
